//! `levels/8v8.lvl`: the 8v8 team map (generated by `scripts/gen_8v8_level.py`), pinned analytically against the
//! real `Cfg` limits and then exercised with the real character controller.
//!
//! The file uses the `spawn x y z team` syntax (team 0 Cyan, 1 Orange), parsed by `parse_level_file` / `parse_spawn_teams`.

use std::collections::VecDeque;

use shinobi_sim::character::{Cfg, CharacterSystem, MoveState, PhysicsWorld, PlayerInput};
use shinobi_sim::level::{parse_level_file, parse_spawn_teams, LevelBox, LevelFile};
use shinobi_sim::movement::step_player;
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::spawn::blocked;

const DT: f32 = 1.0 / 60.0;
const CELL: f32 = 0.5;
const HALF: f32 = 56.0;
const CEILING_Y: f32 = 22.0;
const EYE: f32 = 0.6;

struct Map {
    file: LevelFile,
    /// (position, team) for every spawn line.
    spawns: Vec<([f32; 3], u8)>,
}

fn map() -> Map {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/8v8.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    // the engine parser reads the `spawn x y z team` column itself
    let file = parse_level_file(&text).unwrap_or_else(|e| panic!("8v8.lvl: {e}"));
    let teams = parse_spawn_teams(&text);
    assert_eq!(teams.len(), file.level.spawns.len());
    let spawns = file.level.spawns.iter().copied().zip(teams).collect();
    Map { file, spawns }
}

fn team(m: &Map, t: u8) -> Vec<[f32; 3]> {
    m.spawns.iter().filter(|s| s.1 == t).map(|s| s.0).collect()
}

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld {
        bodies: RigidBodySet::new(),
        colliders: ColliderSet::new(),
        islands: IslandManager::new(),
        queries: QueryPipeline::new(),
    };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

// ---- box geometry (boxes may be rolled about Z) ----

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    u.abs() <= b.half[0] && v.abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

fn any_inside(l: &LevelFile, p: [f32; 3]) -> bool {
    l.level.boxes.iter().any(|b| inside(b, p))
}

fn top_at(b: &LevelBox, x: f32, z: f32) -> Option<f32> {
    if (z - b.center[2]).abs() > b.half[2] {
        return None;
    }
    let (s, c) = b.rot_z.sin_cos();
    let u = (x - b.center[0] + b.half[1] * s) / c;
    (u.abs() <= b.half[0]).then(|| b.center[1] + u * s + b.half[1] * c)
}

fn xy_bounds(b: &LevelBox) -> ([f32; 2], [f32; 2]) {
    let (s, c) = b.rot_z.sin_cos();
    let ex = b.half[0] * c.abs() + b.half[1] * s.abs();
    let ey = b.half[0] * s.abs() + b.half[1] * c.abs();
    ([b.center[0] - ex, b.center[0] + ex], [b.center[1] - ey, b.center[1] + ey])
}

fn key(b: &LevelBox, mx: f32, mz: f32) -> [i64; 7] {
    let q = |v: f32| (v * 1000.0).round() as i64;
    [q(b.center[0] * mx), q(b.center[1]), q(b.center[2] * mz), q(b.half[0]), q(b.half[1]), q(b.half[2]), q(b.rot_z * mx)]
}

// ---- tests: content and fairness ----

#[test]
fn loads_with_eight_spawns_per_team_and_a_real_pickup_set() {
    let m = map();
    assert!(team(&m, 0).len() >= 8 && team(&m, 1).len() >= 8, "8 spawns per team");
    assert_eq!(m.spawns.len(), 16);
    assert!((6..=12).contains(&m.file.pickups.len()), "pickups: {}", m.file.pickups.len());
    assert!(m.file.pickups.iter().all(|p| p.respawn_secs >= 10.0));
    assert!(m.file.level.boxes.len() >= 60);
}

#[test]
fn map_is_mirror_symmetric_across_z_and_x() {
    let m = map();
    for (mx, mz, what) in [(1.0, -1.0, "z"), (-1.0, 1.0, "x")] {
        let mut a: Vec<_> = m.file.level.boxes.iter().map(|b| key(b, 1.0, 1.0)).collect();
        let mut b: Vec<_> = m.file.level.boxes.iter().map(|b| key(b, mx, mz)).collect();
        a.sort();
        b.sort();
        assert_eq!(a, b, "boxes are not symmetric across {what}");
    }
    // Cyan spawns mirror to Orange spawns across z, and each team is symmetric across x
    let q = |p: [f32; 3], mx: f32, mz: f32| [(p[0] * mx * 100.0).round() as i64, (p[1] * 100.0).round() as i64, (p[2] * mz * 100.0).round() as i64];
    let mut cyan: Vec<_> = team(&m, 0).iter().map(|p| q(*p, 1.0, -1.0)).collect();
    let mut orange: Vec<_> = team(&m, 1).iter().map(|p| q(*p, 1.0, 1.0)).collect();
    cyan.sort();
    orange.sort();
    assert_eq!(cyan, orange, "Orange spawns are not the mirror of Cyan's");
    for t in [0, 1] {
        let mut a: Vec<_> = team(&m, t).iter().map(|p| q(*p, 1.0, 1.0)).collect();
        let mut b: Vec<_> = team(&m, t).iter().map(|p| q(*p, -1.0, 1.0)).collect();
        a.sort();
        b.sort();
        assert_eq!(a, b, "team {t} spawns are not x-symmetric");
    }
    let mut p: Vec<_> = m.file.pickups.iter().map(|p| (q(p.pos, 1.0, 1.0), p.respawn_secs as i64)).collect();
    let mut pz: Vec<_> = m.file.pickups.iter().map(|p| (q(p.pos, 1.0, -1.0), p.respawn_secs as i64)).collect();
    let mut px: Vec<_> = m.file.pickups.iter().map(|p| (q(p.pos, -1.0, 1.0), p.respawn_secs as i64)).collect();
    p.sort();
    pz.sort();
    px.sort();
    assert_eq!(p, pz, "pickups not z-symmetric");
    assert_eq!(p, px, "pickups not x-symmetric");
}

#[test]
fn no_spawn_has_a_sight_line_to_the_enemy_base() {
    let m = map();
    let w = world(&m.file);
    // feet, hip and eye of the target; eye of the viewer. A player who can see ANY of that could shoot or be shot.
    let heights = [0.1, 0.81, 0.81 + EYE];
    for a in team(&m, 0) {
        for b in team(&m, 1) {
            for hb in heights {
                let from = [a[0], a[1] + EYE, a[2]];
                let to = [b[0], b[1] - 0.81 + hb, b[2]];
                assert!(blocked(&w, from, to), "Cyan spawn {a:?} sees Orange spawn {b:?} (target height {hb})");
            }
        }
    }
    // and nobody inside one base sees a point in the middle of the other base's rows
    for (a, bz) in team(&m, 0).into_iter().map(|a| (a, 50.0)).chain(team(&m, 1).into_iter().map(|a| (a, -50.0))) {
        for x in [-18.0, -9.0, 0.0, 9.0, 18.0] {
            assert!(blocked(&w, [a[0], a[1] + EYE, a[2]], [x, 1.4, bz]), "spawn {a:?} sees the enemy base at ({x}, {bz})");
        }
    }
}

#[test]
fn spawns_and_pickups_stand_on_solid_ground_and_not_in_geometry() {
    let m = map();
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for (s, t) in &m.spawns {
        for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
            for (ox, oz) in [(0.0, 0.0), (cfg.radius, 0.0), (-cfg.radius, 0.0), (0.0, cfg.radius), (0.0, -cfg.radius)] {
                let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                assert!(!any_inside(&m.file, p), "team {t} spawn {s:?}: capsule point {p:?} is inside geometry");
            }
        }
        let feet = s[1] - reach;
        let ground = m.file.level.boxes.iter().filter_map(|b| top_at(b, s[0], s[2])).filter(|h| (h - feet).abs() < 0.1).count();
        assert!(ground > 0, "team {t} spawn {s:?} floats (feet at {feet})");
        // a ramp within a capsule of a spawn would drop the player onto a slope
        for b in m.file.level.boxes.iter().filter(|b| b.rot_z != 0.0) {
            let (bx, _) = xy_bounds(b);
            let near = s[0] >= bx[0] - 3.0 && s[0] <= bx[1] + 3.0 && (s[2] - b.center[2]).abs() <= b.half[2] + 3.0;
            assert!(!near, "team {t} spawn {s:?} is next to a ramp");
        }
    }
    for p in &m.file.pickups {
        assert!(!any_inside(&m.file, p.pos), "pickup {:?} is inside geometry", p.pos);
        let support = m.file.level.boxes.iter().filter_map(|b| top_at(b, p.pos[0], p.pos[2])).any(|h| (p.pos[1] - h - 1.0).abs() < 0.2);
        assert!(support, "pickup {:?} is not ~1 m above a surface", p.pos);
    }
}

#[test]
fn spawns_are_spread_inside_the_base_and_far_from_the_other_team() {
    let m = map();
    let d = |a: [f32; 3], b: [f32; 3]| ((a[0] - b[0]).powi(2) + (a[2] - b[2]).powi(2)).sqrt();
    for t in [0u8, 1] {
        let ss = team(&m, t);
        for (i, a) in ss.iter().enumerate() {
            for b in &ss[i + 1..] {
                assert!(d(*a, *b) >= 5.0, "team {t} spawns {a:?} / {b:?} only {:.1} m apart", d(*a, *b));
            }
            // behind the 10 m front wall at z = +-42
            let behind = if t == 0 { a[2] < -44.0 } else { a[2] > 44.0 };
            assert!(behind, "team {t} spawn {a:?} is not behind the base wall");
        }
    }
    for a in team(&m, 0) {
        for b in team(&m, 1) {
            assert!(d(a, b) >= 80.0, "enemy spawns {a:?} / {b:?} only {:.1} m apart", d(a, b));
        }
    }
}

#[test]
fn bounds_are_sealed_floor_walls_and_ceiling() {
    let m = map();
    let step = 0.5;
    let n = (2.0 * (HALF + 0.5) / step) as i32;
    let at = |i: i32| -(HALF + 0.5) + i as f32 * step;
    for i in 0..=n {
        let t = at(i);
        for j in 0..=n {
            let u = at(j);
            if t.abs() <= HALF && u.abs() <= HALF {
                assert!(any_inside(&m.file, [t, -0.25, u]), "floor gap at ({t},{u})");
            }
            assert!(any_inside(&m.file, [t, CEILING_Y + 0.25, u]), "ceiling gap at ({t},{u})");
        }
        let mut y = 0.0;
        while y <= CEILING_Y {
            for p in [[-HALF - 0.25, y, t], [HALF + 0.25, y, t], [t, y, -HALF - 0.25], [t, y, HALF + 0.25]] {
                assert!(any_inside(&m.file, p), "perimeter gap at {p:?}");
            }
            y += 0.5;
        }
    }
}

// ---- walking reachability ----

struct Grid {
    n: usize,
    nodes: Vec<Vec<f32>>,
}

impl Grid {
    fn idx(&self, ix: usize, iz: usize) -> usize {
        iz * self.n + ix
    }
    fn cell(&self, x: f32) -> usize {
        (((x + HALF) / CELL) as isize).clamp(0, self.n as isize - 1) as usize
    }
    fn centre(&self, i: usize) -> f32 {
        -HALF + (i as f32 + 0.5) * CELL
    }
}

fn standable(l: &LevelFile, cfg: &Cfg, x: f32, z: f32, own: usize, h: f32) -> bool {
    let r = cfg.radius;
    let body_top = h + 2.0 * (cfg.half_height + cfg.radius);
    for (i, b) in l.level.boxes.iter().enumerate() {
        if i == own {
            continue;
        }
        let (bx, by) = xy_bounds(b);
        let overlaps = x >= bx[0] - r && x <= bx[1] + r && (z - b.center[2]).abs() <= b.half[2] + r;
        if overlaps && by[1] > h + 0.35 && by[0] < body_top {
            return false;
        }
    }
    true
}

fn build_grid(l: &LevelFile, cfg: &Cfg) -> Grid {
    let n = (2.0 * HALF / CELL) as usize;
    let mut g = Grid { n, nodes: vec![Vec::new(); n * n] };
    for iz in 0..n {
        for ix in 0..n {
            let (x, z) = (g.centre(ix), g.centre(iz));
            let mut hs: Vec<f32> = Vec::new();
            for (i, b) in l.level.boxes.iter().enumerate() {
                if b.rot_z.abs() > 45f32.to_radians() {
                    continue;
                }
                if let Some(h) = top_at(b, x, z) {
                    if standable(l, cfg, x, z, i, h) {
                        hs.push(h);
                    }
                }
            }
            hs.sort_by(|a, b| a.partial_cmp(b).unwrap());
            hs.dedup_by(|a, b| (*a - *b).abs() < 0.05);
            let k = g.idx(ix, iz);
            g.nodes[k] = hs;
        }
    }
    g
}

fn max_rise(cfg: &Cfg) -> f32 {
    let apex = |v: f32| v * v / (2.0 * cfg.gravity);
    let w = cfg.peak_window;
    let at_window = (cfg.jump_speed * cfg.jump_speed - w * w) / (2.0 * cfg.gravity);
    at_window + apex(cfg.double_jump_speed) - 0.3
}

fn reachable(g: &Grid, cfg: &Cfg, start: (usize, usize, f32)) -> Vec<Vec<bool>> {
    let rise = max_rise(cfg);
    let mut seen: Vec<Vec<bool>> = g.nodes.iter().map(|v| vec![false; v.len()]).collect();
    let find = |k: usize, h: f32| g.nodes[k].iter().position(|n| (n - h).abs() < 0.06);
    let s = find(g.idx(start.0, start.1), start.2).expect("start surface exists");
    let mut q = VecDeque::new();
    seen[g.idx(start.0, start.1)][s] = true;
    q.push_back((start.0, start.1, s));
    while let Some((ix, iz, si)) = q.pop_front() {
        let h = g.nodes[g.idx(ix, iz)][si];
        for dz in -2i32..=2 {
            for dx in -2i32..=2 {
                if dx == 0 && dz == 0 {
                    continue;
                }
                let far = dx.abs() == 2 || dz.abs() == 2;
                let (jx, jz) = (ix as i32 + dx, iz as i32 + dz);
                if jx < 0 || jz < 0 || jx >= g.n as i32 || jz >= g.n as i32 {
                    continue;
                }
                let k = g.idx(jx as usize, jz as usize);
                for (ni, n) in g.nodes[k].iter().enumerate() {
                    let up = n - h;
                    let ok = if far { up > 0.35 && up <= rise } else { up <= rise };
                    if ok && !seen[k][ni] {
                        seen[k][ni] = true;
                        q.push_back((jx as usize, jz as usize, ni));
                    }
                }
            }
        }
    }
    seen
}

fn is_reached(g: &Grid, seen: &[Vec<bool>], x: f32, z: f32, h: f32, tol: f32) -> bool {
    let k = g.idx(g.cell(x), g.cell(z));
    g.nodes[k].iter().enumerate().any(|(i, n)| (n - h).abs() <= tol && seen[k][i])
}

#[test]
fn both_bases_the_centre_and_the_shelves_are_walkable_from_every_spawn() {
    let m = map();
    let cfg = Cfg::default();
    let g = build_grid(&m.file, &cfg);
    let s0 = team(&m, 0)[0];
    let seen = reachable(&g, &cfg, (g.cell(s0[0]), g.cell(s0[2]), 0.0));
    for (s, t) in &m.spawns {
        assert!(is_reached(&g, &seen, s[0], s[2], 0.0, 0.06), "team {t} spawn {s:?} unreachable from Cyan spawn 0");
    }
    // tiers on both sides of both axes: towers 1.2 / 2.4 / 3.6, shelves 1.2 / 2.4 / 3.6
    for sx in [-1.0f32, 1.0] {
        for sz in [-1.0f32, 1.0] {
            for (x, z, h, what) in [
                (16.0 + 5.5, 0.0, 1.2, "tower tier 1"),
                (16.0 + 3.5, 0.0, 2.4, "tower tier 2"),
                (16.0 + 2.1, 2.1, 3.6, "tower tier 3"),
                (47.5, 20.0, 1.2, "shelf tier 1"),
                (51.0, 20.0, 2.4, "shelf tier 2"),
                (53.5, 14.0, 3.6, "shelf tier 3"),
            ] {
                let (px, pz) = (sx * x, sz * z);
                assert!(is_reached(&g, &seen, px, pz, h, 0.06), "{what} at ({px}, {pz}) = {h} m is unreachable on foot");
            }
        }
    }
    for p in &m.file.pickups {
        let h = p.pos[1] - 1.0;
        let on_foot = is_reached(&g, &seen, p.pos[0], p.pos[2], h, 0.15);
        // the taller jump (held jump + double jump ~5 m) reaches the lowest pillar-top pickups from a tower: only the
        // really high ones (> 8 m) are grapple-only now
        if h <= 6.0 {
            assert!(on_foot, "pickup {:?} must be reachable on foot", p.pos);
        } else if h > 8.0 {
            assert!(!on_foot, "pickup {:?}: grapple-only pickups are the high pillar tops", p.pos);
        }
    }
}

// ---- real controller on the real file ----

fn player_in(l: &LevelFile, at: [f32; 3]) -> (PhysicsWorld, CharacterSystem) {
    let cfg = Cfg::default();
    let mut w = world(l);
    let body = w.bodies.insert(RigidBodyBuilder::kinematic_position_based().translation(vector![at[0], at[1], at[2]]).build());
    w.colliders.insert_with_parent(ColliderBuilder::capsule_y(cfg.half_height, cfg.radius).build(), body, &mut w.bodies);
    (w, CharacterSystem::new(body, cfg))
}

fn pos(w: &PhysicsWorld, ch: &CharacterSystem) -> Vector<Real> {
    *w.bodies[ch.body].translation()
}

#[test]
fn every_lane_sustains_a_wall_run_for_its_length() {
    let m = map();
    // lanes: (x of the wall to run along, side facing the lane, start z, run direction z, label)
    for (wall_x, start_x, label) in [(-26.8 - 0.5, -27.3 - 0.4, "west lane inner wall"), (26.8 + 0.5, 27.3 + 0.4, "east lane inner wall")] {
        let _ = wall_x;
        for dir in [-1.0f32, 1.0] {
            let (mut w, mut ch) = player_in(&m.file, [start_x, 1.6, -dir * 12.0]);
            ch.vel = vector![0.0, 0.0, dir * 9.0];
            let mut now = 0.0;
            let mut ticks = 0;
            for _ in 0..90 {
                step_player(&mut ch, &PlayerInput { move_dir: vector![0.0, 0.0, dir], wall_cling: true, ..Default::default() }, &mut w, now, DT);
                now += DT;
                ticks += matches!(ch.state, MoveState::WallRun { .. }) as u32;
            }
            let travelled = (pos(&w, &ch).z + dir * 12.0).abs();
            assert!(ticks >= 85, "{label} dir {dir}: wall-run only held {ticks}/90 ticks");
            assert!(travelled >= 10.0, "{label} dir {dir}: ran only {travelled:.1} m");
        }
    }
}

#[test]
fn the_central_spine_is_a_wall_run_lane_too() {
    let m = map();
    let (mut w, mut ch) = player_in(&m.file, [2.5, 1.6, 10.0]);
    ch.vel = vector![0.0, 0.0, -9.0];
    let mut now = 0.0;
    let mut ticks = 0;
    for _ in 0..80 {
        step_player(&mut ch, &PlayerInput { move_dir: vector![0.0, 0.0, -1.0], wall_cling: true, ..Default::default() }, &mut w, now, DT);
        now += DT;
        ticks += matches!(ch.state, MoveState::WallRun { .. }) as u32;
    }
    assert!(ticks >= 70, "spine wall-run held {ticks}/80 ticks");
}

#[test]
fn ramps_walk_up_to_the_towers_and_shelves() {
    let m = map();
    // west tower inner ramp, running toward the tower (+x for the west tower is -x)
    let (mut w, mut ch) = player_in(&m.file, [-5.0, 0.81, 0.0]);
    let mut now = 0.0;
    for _ in 0..150 {
        step_player(&mut ch, &PlayerInput { move_dir: vector![-1.0, 0.0, 0.0], ..Default::default() }, &mut w, now, DT);
        now += DT;
    }
    let p = pos(&w, &ch);
    assert!(ch.state == MoveState::Grounded && p.y > 1.2 + 0.79, "stuck on the tower ramp at {p:?} ({:?})", ch.state);
    let (mut w, mut ch) = player_in(&m.file, [40.0, 0.81, -12.0]);
    let mut now = 0.0;
    for _ in 0..150 {
        step_player(&mut ch, &PlayerInput { move_dir: vector![1.0, 0.0, 0.0], ..Default::default() }, &mut w, now, DT);
        now += DT;
    }
    let p = pos(&w, &ch);
    assert!(ch.state == MoveState::Grounded && p.y > 1.2 + 0.79, "stuck on the shelf ramp at {p:?} ({:?})", ch.state);
}

fn aim(from: [f32; 3], to: [f32; 3]) -> Vector<Real> {
    vector![to[0] - from[0], to[1] - from[1], to[2] - from[2]]
}

#[test]
fn grapple_anchors_are_hookable_from_the_lanes_and_the_floor() {
    let m = map();
    let cfg = Cfg::default();
    // (stand position, anchor point to aim at, label)
    for (stand, target, label) in [
        ([30.1, 0.81, -10.0], [30.0, 10.6, -24.0], "lane-mouth slab from inside the east lane"),
        ([-30.1, 0.81, 10.0], [-30.0, 10.6, 24.0], "lane-mouth slab from inside the west lane (Orange side)"),
        ([36.0, 0.81, -10.0], [40.0, 12.6, -10.0], "flank slab from the flank gap"),
        ([36.0, 0.81, -30.0], [40.0, 12.6, -30.0], "far slab from the lane mouth"),
        ([36.0, 0.81, -22.0], [38.5, 9.0, -22.0], "pylon side from the flank gap"),
        ([30.1, 0.81, 22.0], [22.0, 11.6, 22.0], "yard slab from the east lane (Orange side)"),
    ] {
        let (mut w, mut ch) = player_in(&m.file, stand);
        let mut now = 0.0;
        for _ in 0..5 {
            step_player(&mut ch, &PlayerInput::default(), &mut w, now, DT);
            now += DT;
        }
        let eye = [stand[0], stand[1] + cfg.eye_above_center, stand[2]];
        step_player(&mut ch, &PlayerInput { grapple_aim: Some(aim(eye, target)), ..Default::default() }, &mut w, now, DT);
        let g = ch.grapple.unwrap_or_else(|| panic!("{label}: the hook found nothing to grab"));
        let d = ((g.anchor.x - target[0]).powi(2) + (g.anchor.y - target[1]).powi(2) + (g.anchor.z - target[2]).powi(2)).sqrt();
        assert!(d < 1.0, "{label}: anchored {:?}, aimed at {target:?}", g.anchor);
    }
}

#[test]
fn a_grapple_from_the_lane_lifts_a_player_onto_the_flank_shelf_height() {
    let m = map();
    let (mut w, mut ch) = player_in(&m.file, [36.0, 0.81, -10.0]);
    let mut now = 0.0;
    for _ in 0..5 {
        step_player(&mut ch, &PlayerInput::default(), &mut w, now, DT);
        now += DT;
    }
    let eye = [36.0, 0.81 + 0.6, -10.0];
    step_player(&mut ch, &PlayerInput { grapple_aim: Some(aim(eye, [40.0, 12.6, -10.0])), ..Default::default() }, &mut w, now, DT);
    assert!(ch.grapple.is_some());
    let mut top = 0.0f32;
    for _ in 0..120 {
        now += DT;
        step_player(&mut ch, &PlayerInput::default(), &mut w, now, DT);
        top = top.max(pos(&w, &ch).y);
    }
    assert!(top > 8.0, "the reel only lifted the player to {top:.1} m");
}

#[test]
fn the_pillar_pickups_are_grapple_only_and_the_grapple_gets_you_there() {
    // From the tower's first tier, hook the pillar's top front edge, reel up, steer onto the 6.6 m top.
    let m = map();
    for sx in [-1.0f32, 1.0] {
        for sz in [-1.0f32, 1.0] {
            let (cx, from_z) = (sx * 16.0, sz * -6.5);
            let (mut w, mut ch) = player_in(&m.file, [cx, 1.2 + 0.81, from_z]);
            let mut now = 0.0;
            for _ in 0..10 {
                step_player(&mut ch, &PlayerInput::default(), &mut w, now, DT);
                now += DT;
            }
            let eye = [cx, 1.2 + 0.81 + 0.6, from_z];
            let edge = [cx, 6.59, sz * -1.5];
            step_player(&mut ch, &PlayerInput { grapple_aim: Some(aim(eye, edge)), ..Default::default() }, &mut w, now, DT);
            assert!(ch.grapple.is_some(), "pillar edge not hookable from the tier ({cx}, {from_z})");
            let mut on_top = false;
            for _ in 0..300 {
                now += DT;
                let p = pos(&w, &ch);
                let to = vector![cx - p.x, 0.0, -p.z];
                let dir = if to.norm() > 0.2 && p.y > 5.0 { to.normalize() } else { vector![0.0, 0.0, 0.0] };
                // skilled play: jump-release when close to the anchor for the hop boost
                let close = ch.grapple.map_or(false, |g| (g.anchor - vector![p.x, p.y + 0.6, p.z]).norm() < 3.2);
                step_player(&mut ch, &PlayerInput { move_dir: dir, jump_pressed: close, jump_held: close, ..Default::default() }, &mut w, now, DT);
                on_top |= ch.state == MoveState::Grounded && pos(&w, &ch).y > 7.0;
            }
            assert!(on_top, "grapple + steering did not land on the pillar top at x = {cx}");
        }
    }
}

#[test]
fn rope_feel_budget_smooth_pull_capped_speed_no_face_plants() {
    // Every anchor type on the map, from where a player would use it: while on the rope the acceleration stays at the
    // designed pull (no spikes), the speed never passes the cap, the pull eases in, and the player is not driven into
    // the surface at full reel speed (the closing speed inside the release radius is limited).
    let m = map();
    let cfg = Cfg::default();
    for (label, stand, target) in [
        ("flank slab from the flank gap", [36.0, 0.81, -10.0], [40.0, 12.6, -10.0]),
        ("lane-mouth slab from inside the lane", [30.1, 0.81, -10.0], [30.0, 10.6, -24.0]),
        ("lane-mouth slab from the yard", [30.0, 0.81, -30.0], [30.0, 10.6, -24.0]),
        ("pylon from the flank gap", [36.0, 0.81, -22.0], [38.5, 9.0, -22.0]),
        ("pillar edge from the tower tier", [16.0, 1.2 + 0.81, -6.5], [16.0, 6.59, -1.5]),
    ] {
        let (mut w, mut ch) = player_in(&m.file, stand);
        let mut now = 0.0;
        for _ in 0..10 {
            step_player(&mut ch, &PlayerInput::default(), &mut w, now, DT);
            now += DT;
        }
        let eye = [stand[0], stand[1] + cfg.eye_above_center, stand[2]];
        step_player(&mut ch, &PlayerInput { grapple_aim: Some(aim(eye, target)), ..Default::default() }, &mut w, now, DT);
        assert!(ch.grapple.is_some(), "{label}: no hook");
        let (mut prev, mut max_a, mut max_v, mut first_a) = (ch.vel, 0.0f32, 0.0f32, None);
        let mut ticks = 0;
        while ch.grapple.is_some() && ticks < 400 {
            now += DT;
            step_player(&mut ch, &PlayerInput::default(), &mut w, now, DT);
            ticks += 1;
            let a = (ch.vel - prev).norm() / DT;
            prev = ch.vel;
            first_a.get_or_insert(a);
            if ch.grapple.is_some() {
                max_a = max_a.max(a);
                max_v = max_v.max(ch.vel.norm());
            }
        }
        assert!(ticks < 400, "{label}: rope never ended");
        assert!(max_v <= cfg.grapple_far_speed + 2.5, "{label}: speed {max_v} over the far-reel cap");
        // pull and brake scale with the reel speed (`scale` in grapple_pull): a 140 m/s far reel pulls 140/18 times harder
        let scale = cfg.grapple_far_speed / cfg.grapple_speed;
        assert!(max_a <= cfg.grapple_accel * scale * 1.35 + cfg.gravity, "{label}: acceleration spike {max_a:.0} m/s^2 on the rope");
        assert!(first_a.unwrap() < cfg.grapple_accel * scale * 0.6 + cfg.gravity, "{label}: the pull must ease in, first tick {:.0} m/s^2", first_a.unwrap());
    }
}
